    .hero-subtitle {
      font-size: 1.25rem;
      color: var(--text-secondary);
      margin-bottom: 0.5rem;
    }

    .hero-subtitle span {
      color: var(--text-primary);
      font-weight: 600;
    }

    .hero-prompt {
      font-size: 1rem;
      color: var(--text-secondary);
      margin-bottom: 2rem;
      margin-top: 1rem;
    }

    .email-form {
      display: flex;
      gap: 0;
      max-width: 500px;
      margin: 0 auto;
    }

    .email-form input {
      flex: 1;
      padding: 1rem 1.25rem;
      font-size: 1rem;
      border: 1px solid rgba(255,255,255,0.2);
      border-right: none;
      background: rgba(0,0,0,0.6);
      color: white;
      border-radius: 4px 0 0 4px;
      outline: none;
      transition: border-color 0.2s;
    }

    .email-form input:focus {
      border-color: var(--accent);
    }

    .email-form input::placeholder {
      color: var(--text-secondary);
    }

    .btn-get-started {
      background: var(--accent);
      color: white;
      border: none;
      padding: 1rem 2rem;
      font-size: 1rem;
      font-weight: 600;
      border-radius: 0 4px 4px 0;
      cursor: pointer;
      transition: background 0.2s;
      white-space: nowrap;
    }

    .btn-get-started:hover { background: var(--accent-hover); }

    /* Trending */
    .trending {
      padding: 4rem 2rem;
      background: var(--bg-primary);
    }

    .section-title {
      font-family: 'Bebas Neue', sans-serif;
      font-size: clamp(1.75rem, 4vw, 2.5rem);
      letter-spacing: 2px;
      margin-bottom: 2rem;
    }

    .carousel-container {
      position: relative;
      max-width: 1400px;
      margin: 0 auto;
    }

    .carousel {
      display: flex;
      gap: 1rem;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 1rem 0;
    }

    .carousel::-webkit-scrollbar { display: none; }

    .carousel-item {
      position: relative;
      flex-shrink: 0;
      width: 200px;
      cursor: pointer;
      transition: transform 0.3s ease;
    }

    .carousel-item:hover { transform: scale(1.05); }

    .carousel-rank {
      position: absolute;
      top: -0.5rem;
      left: -0.5rem;
      font-family: 'Bebas Neue', sans-serif;
      font-size: 6rem;
      line-height: 1;
      color: var(--bg-secondary);
      -webkit-text-stroke: 2px rgba(255,255,255,0.3);
      text-stroke: 2px rgba(255,255,255,0.3);
      z-index: 1;
      pointer-events: none;
    }

    .carousel-poster {
      width: 100%;
      aspect-ratio: 2/3;
      background: var(--bg-tertiary);
      border-radius: 8px;
      overflow: hidden;
      position: relative;
    }

    .carousel-poster img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .carousel-poster::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, transparent 50%);
    }

    .carousel-title {
      position: absolute;
      bottom: 0.5rem;
      left: 0.5rem;
      right: 0.5rem;
      font-weight: 600;
      font-size: 0.875rem;
      z-index: 2;
    }

    .carousel-nav {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      background: var(--accent);
      border: none;
      border-radius: 50%;
      color: white;
      font-size: 1.5rem;
      cursor: pointer;
      z-index: 10;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s, opacity 0.2s;
    }

    .carousel-nav:hover { background: var(--accent-hover); }
    .carousel-nav:disabled { opacity: 0.3; cursor: default; }

    .carousel-nav.prev { left: -24px; }
    .carousel-nav.next { right: -24px; }

    /* Features */
    .features {
      padding: 4rem 2rem;
      background: var(--bg-secondary);
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 2rem;
      max-width: 1200px;
      margin: 0 auto;
    }

    .feature-card {
      background: var(--bg-tertiary);
      border-radius: 12px;
      padding: 2rem;
      position: relative;
      overflow: hidden;
      transition: transform 0.3s ease;
    }

    .feature-card:hover { transform: translateY(-5px); }

    .feature-card h3 {
      font-size: 1.125rem;
      font-weight: 600;
      margin-bottom: 0.75rem;
    }

    .feature-card p {
      color: var(--text-secondary);
      font-size: 0.875rem;
      line-height: 1.5;
    }

    .feature-icon {
      position: absolute;
      bottom: 1rem;
      right: 1rem;
      font-size: 3rem;
      opacity: 0.1;
    }

    /* FAQ */
    .faq {
      padding: 4rem 2rem;
      background: var(--bg-primary);
    }

    .faq-container {
      max-width: 800px;
      margin: 0 auto;
    }

    .faq-item {
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .faq-question {
      width: 100%;
      background: none;
      border: none;
      color: var(--text-primary);
      padding: 1.25rem 0;
      font-size: 1.125rem;
      font-weight: 500;
      text-align: left;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      transition: color 0.2s;
    }

    .faq-question:hover { color: var(--accent); }

    .faq-question::after {
      content: '+';
      font-size: 1.5rem;
      transition: transform 0.3s ease;
    }

    .faq-item.active .faq-question::after {
      transform: rotate(45deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease, padding 0.3s ease;
    }

    .faq-item.active .faq-answer {
      max-height: 500px;
      padding-bottom: 1.5rem;
    }

    .faq-answer p {
      color: var(--text-secondary);
      line-height: 1.7;
    }

    /* CTA Section */
    .cta-section {
      padding: 5rem 2rem;
      background: linear-gradient(135deg, #1a0a0a 0%, #0a0a0a 100%);
      text-align: center;
      position: relative;
    }

    .cta-section::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at center, rgba(229,9,20,0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .cta-content {
      position: relative;
      z-index: 1;
      max-width: 600px;
      margin: 0 auto;
    }

    .cta-section h2 {
      font-family: 'Bebas Neue', sans-serif;
      font-size: clamp(2rem, 5vw, 3rem);
      letter-spacing: 2px;
      margin-bottom: 1rem;
    }

    .cta-section .hero-prompt {
      margin-bottom: 2rem;
    }

    /* Footer */
    footer {
      padding: 3rem 2rem;
      background: var(--bg-secondary);
      border-top: 1px solid rgba(255,255,255,0.05);
    }

    .footer-content {
      max-width: 1000px;
      margin: 0 auto;
    }

    .footer-contact {
      color: var(--text-secondary);
      margin-bottom: 2rem;
    }

    .footer-links {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 1.5rem;
      margin-bottom: 2rem;
    }

    .footer-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 0.875rem;
      transition: color 0.2s;
    }

    .footer-links a:hover { color: var(--text-primary); }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 1rem;
      padding-top: 2rem;
      border-top: 1px solid rgba(255,255,255,0.05);
    }

    .footer-bottom p {
      color: var(--text-secondary);
      font-size: 0.75rem;
    }

    /* Mobile Styles */
    @media (max-width: 768px) {
      header { padding: 1rem; }
      .logo { font-size: 1.75rem; }
      .language-select { display: none; }

      .email-form {
        flex-direction: column;
        gap: 0.75rem;
      }

      .email-form input {
        border-right: 1px solid rgba(255,255,255,0.2);
        border-radius: 4px;
      }

      .btn-get-started {
        border-radius: 4px;
        padding: 1rem;
      }

      .carousel-nav { display: none; }
      .carousel { overflow-x: scroll; -webkit-overflow-scrolling: touch; }

      .features-grid { grid-template-columns: 1fr; }

      .footer-links { grid-template-columns: repeat(2, 1fr); }
      .footer-bottom { flex-direction: column; text-align: center; }
    }

    @media (max-width: 480px) {
      .hero h1 { font-size: 2.5rem; }
      .hero-subtitle { font-size: 1rem; }
      .carousel-item { width: 140px; }
      .carousel-rank { font-size: 4rem; }
    }
  </style>
</head>
